"""Only DWG delivery, guarded by saved geometry, active-document audit and closure."""
from pathlib import Path
import json,hashlib,subprocess,sys,shutil
S=Path(__file__).resolve().parent;P=S.parent/'阶段1/原生接口探测';V='-v63'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest().upper()
def require(v,m):
 if not v:raise RuntimeError(m)
subprocess.run([sys.executable,str(S/'verify_anchored_direct_dimensions.py'),'--'+V[1:],'--check-only'],check=True)
n=read(S/f'evidence/native-run{V}.json');g=read(S/f'evidence/anchored-direct-release{V}-final.json');c=read(S/f'evidence/host-closure{V}.json');review=read(S/f'evidence/anchored-direct-independent-review{V}.json')
require(g['passed'] and g['DWGSHA256']==n['DWGSHA256'],'geometry receipt mismatch')
require(review['verdict']=='No findings' and review['DWGSHA256']==n['DWGSHA256'] and review['sourceFiles']==n['binding']['sourceFiles'],'review source/native binding differs')
require(Path(c['session']).resolve()==Path(n['session']).resolve() and c['final']['session']==n['session'] and c['final']['nonce']==n['nonce'] and c['final']['processId']==n['processId'],'closure belongs to another native session')
finalPath=Path(c['finalPath']);require(finalPath.parent.resolve()==Path(n['session']).resolve() and finalPath.name in ('isolation-final.json','isolation-host-final.json') and read(finalPath)==c['final'],'actual final host evidence differs')
require(all(x['snapshotUnchanged']for x in c['inputs']) and not c['process']['ownProcessAlive'] and c['stagingRemoved'],'closure incomplete')
require(all(x['LOADCTRLS']==2 and x['action']=='read only'for x in c['sharedRegistrations']),'shared registrations differ')
f=c['final'];require(f['monitorError'] is None and not f['supervisorErrors'] and f['inputDesktopReadErrors']==0 and f['droppedEvents']==0 and f['workerUserDesktopShowEvents']==f['workerForegroundEvents']==f['workerForegroundSamples']==0,'own window monitoring incomplete')
launch=read(Path(n['session'])/'isolation-host-receipt.json');require(launch['nonce']==n['nonce'] and launch['processId']==n['processId'] and not launch['metadataErrors'] and launch['controllerSHA256']==sha(P/'启动隔离桌面宿主.ps1')==sha(Path(n['session'])/'candidate/启动隔离桌面宿主.ps1') and launch['nativeHelperSHA256']==sha(P/'IsolatedCadHostNative.cs'),'monitor/controller binding differs')
require(review['monitorControllerSHA256']==launch['controllerSHA256'],'monitor review differs')
for diagnostic in f.get('postExitWindowDiagnostics',[]):require(diagnostic['nonce']==n['nonce'] and diagnostic['processId']==n['processId'] and diagnostic['originalProcessHandleSignaled'] and diagnostic['operation']=='EnumDesktopWindows private desktop' and diagnostic['exitCode']==f['workerExitCode'] and str(diagnostic['creationFileTime'])==str(launch['creationFileTime']),'invalid post-exit private snapshot diagnostic')
for name,h in n['binding']['sourceFiles'].items():require(sha(S/'src'/name)==h,'source changed: '+name)
candidate=Path(n['session'])/'phase2-candidate'/Path(n['binding']['module']).name;require(sha(candidate)==n['binding']['moduleSHA256']==sha(S/'bin/BuildingPlan2020.arx'),'binary binding differs')
cfg=read(Path(n['session'])/'worker-config.json');require(sha(P/'bin/NativeAccessProbe.arx')==cfg['binarySHA256']==n['binding']['bridgeARXSHA256'],'bridge binary differs')
for name,h in cfg['sourceFiles'].items():require(sha(P/'src'/name)==h,'bridge source changed: '+name)
require(review['bridgeSourceFiles']==cfg['sourceFiles'],'bridge review differs')
for name,h in g['gateDependencies'].items():require(sha(S/name)==h,'gate dependency changed: '+name)
require(sha(S/'verify_anchored_direct_dimensions.py')==g['gateScriptSHA256'],'gate script changed')
standard=read(S/'inputs/layer-standard-20261031/source.json');require(sha(Path(standard['source']))==sha(Path(standard['snapshot']))==standard['SHA256'],'standard changed')
prefix=read(S/'inputs/user-opening-prefixes-v1.json');require(sha(Path(prefix['path']))==prefix['SHA256'] and Path(prefix['path']).read_text(encoding='utf-8')==(Path(n['output'])/'opening-prefixes.tsv').read_text(encoding='utf-8'),'C prefixes differ')
env=read(Path(n['output'])/'native-mask-frame-environment.json');require(env['enabled'] and env['applied']==0 and env['restored'],'own scratch variables not restored')
source=Path(n['output'])/'方案施工图_阶段2中间图.dwg';require(sha(source)==g['DWGSHA256'],'source DWG differs')
out=S/'交付/编号贴洞口与第三道原生尺寸_20261031';require(not out.exists(),'never overwrite prior delivery');out.mkdir(parents=True);target=out/'方案施工图_编号贴洞口与第三道原生尺寸.dwg';shutil.copyfile(source,target);require(sha(target)==g['DWGSHA256'],'published DWG differs');require(list(out.iterdir())==[target],'DWG only')
result=dict(contract='bcp.anchored-direct-delivery.v1',DWG=str(target),DWGSHA256=sha(target),ARXSHA256=n['binding']['moduleSHA256'],gateSHA256=sha(S/f'evidence/anchored-direct-release{V}-final.json'),reviewSHA256=sha(S/f'evidence/anchored-direct-independent-review{V}.json'),closureSHA256=sha(S/f'evidence/host-closure{V}.json'),PDFDelivered=False,constructionDrawingComplete=False)
receipt=S/f'evidence/anchored-direct-delivery{V}.json';require(not receipt.exists(),'receipt exists');receipt.write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8');print(json.dumps(result,ensure_ascii=False))
